mapper.select:
WITH profile AS ( SELECT genetic_profile.genetic_profile_id AS id, cancer_study.cancer_study_identifier AS study_id FROM genetic_profile INNER JOIN cancer_study ON cancer_study.cancer_study_id = genetic_profile.cancer_study_id WHERE genetic_profile.stable_id = #{molecularProfileId} ), sample_order AS ( SELECT genetic_profile_id AS profile_id, splitByChar(',', ordered_sample_list) AS sample_ids FROM genetic_profile_samples WHERE genetic_profile_id IN (SELECT id FROM profile) ), entries AS ( SELECT geneset.external_id AS geneset_id, arrayJoin( arrayZip( sample_order.sample_ids, arrayResize(splitByChar(',', genetic_alteration.`values`), length(sample_order.sample_ids), '') ) ) AS entry FROM genetic_alteration INNER JOIN geneset ON geneset.genetic_entity_id = genetic_alteration.genetic_entity_id INNER JOIN sample_order ON sample_order.profile_id = genetic_alteration.genetic_profile_id WHERE genetic_alteration.genetic_profile_id IN (SELECT id FROM profile)
AND geneset.external_id IN #{item}
) SELECT #{molecularProfileId} AS "molecularProfileId", s.sample_stable_id AS "sampleId", s.patient_stable_id AS "patientId", s.cancer_study_identifier AS "studyId", entries.geneset_id AS "genesetId",
FROM entries INNER JOIN sample_derived s ON s.internal_id = toInt64OrZero(entries.entry.1) WHERE s.cancer_study_identifier IN (SELECT study_id FROM profile)
AND s.sample_stable_id IN #{item}
